// Efficient insertion into vector (avoiding unnecessary copies)
struct Resource { Resource(int x){} };
std::vector<Resource> resources;

// Construct element in place (preferred for complex objects)
resources.emplace_back(10);

Resource temp(5);
// Requires move to avoid copying temporary
resources.push_back(std::move(temp));
